using Microsoft.AspNetCore.Mvc;using RaceDay.Mvc.Filters;using RaceDay.Mvc.Services;
namespace RaceDay.Mvc.Controllers;
[RequireRole("Organiser")]public class OrganiserController(RaceDayApiClient api):Controller{
 public async Task<IActionResult> Index(){var events=await api.Get("api/events");var counts=new Dictionary<int,int>();foreach(var e in events.EnumerateArray()){var id=e.GetProperty("eventId").GetInt32();try{counts[id]=(await api.Get($"api/enrolments/event/{id}")).GetArrayLength();}catch{counts[id]=0;}}ViewBag.Events=events;ViewBag.EnrolmentCounts=counts;return View();}
 public async Task<IActionResult> Events(){ViewBag.Events=await api.Get("api/events");ViewBag.Types=await api.Get("api/event-types");return View();}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> CreateEvent(string name,string description,DateTime eventDate,string location,decimal distanceKm,int eventTypeId,IFormFile? banner){var r=await api.Post("api/events",new{name,description,eventDate,location,distanceKm,eventTypeId});if(!r.Ok){TempData["Error"]=r.Message;return RedirectToAction(nameof(Events));}if(banner!=null&&banner.Length>0){var created=await api.Get("api/events");var ev=created.EnumerateArray().FirstOrDefault(x=>x.GetProperty("name").GetString()==name);if(ev.ValueKind!=System.Text.Json.JsonValueKind.Undefined){var up=await api.Upload($"api/events/{ev.GetProperty("eventId").GetInt32()}/banner",banner);TempData[up.Ok?"Success":"Error"]=up.Message;}}else TempData["Success"]=r.Message;return RedirectToAction(nameof(Events));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> UpdateEvent(int id,string name,string description,DateTime eventDate,string location,decimal distanceKm,int eventTypeId){var r=await api.Put($"api/events/{id}",new{name,description,eventDate,location,distanceKm,eventTypeId});TempData[r.Ok?"Success":"Error"]=r.Message;return RedirectToAction(nameof(Events));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> DeleteEvent(int id){var r=await api.Delete($"api/events/{id}");TempData[r.Ok?"Success":"Error"]=r.Message;return RedirectToAction(nameof(Events));}
 public async Task<IActionResult> Categories(int id){ViewBag.EventId=id;ViewBag.Categories=await api.Get($"api/events/{id}/categories");return View();}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> AddCategory(int eventId,string name,string categoryType,int? minimumAge,int? maximumAge,decimal? distanceKm){var r=await api.Post($"api/events/{eventId}/categories",new{name,categoryType,minimumAge,maximumAge,distanceKm});TempData[r.Ok?"Success":"Error"]=r.Message;return RedirectToAction(nameof(Categories),new{id=eventId});}
 public async Task<IActionResult> Enrolments(int id){ViewBag.EventId=id;ViewBag.Items=await api.Get($"api/enrolments/event/{id}");return View();}
 public async Task<IActionResult> Results(int id){ViewBag.EventId=id;ViewBag.Items=await api.Get($"api/enrolments/event/{id}");return View();}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> SaveResult(int eventId,int enrolmentId,TimeSpan finishTime,int finishingPosition){var r=await api.Post($"api/results/enrolment/{enrolmentId}",new{finishTime,finishingPosition});if(!r.Ok&&r.Message.Contains("already exists",StringComparison.OrdinalIgnoreCase))r=await api.Put($"api/results/enrolment/{enrolmentId}",new{finishTime,finishingPosition});TempData[r.Ok?"Success":"Error"]=r.Message;return RedirectToAction(nameof(Results),new{id=eventId});}
}